// StringBase members that change a buffer's reference count, under the string
// lock (target: 0x000365F0/0x00037050 copy constructor, 0x000366F0/0x00037150
// set(const StringBase &), 0x00036410/0x00036E70 releaseBuffer; the lock
// expands inline in each: test CriticalSection +0x20, Enter/LeaveCriticalSection
// on +8).
template <class CharT>
StringBase<CharT>::StringBase(const StringBase<CharT> &src)
{
	ScopedCriticalSection lock(getStringCriticalSection<CharT>());
	m_data = src.m_data;
	if (m_data)
		++m_data->refCount;
}

template <class CharT>
void StringBase<CharT>::set(const StringBase<CharT> &src)
{
	ScopedCriticalSection lock(getStringCriticalSection<CharT>());
	if (&src != this)
	{
		releaseBuffer();
		m_data = src.m_data;
		if (m_data)
			++m_data->refCount;
	}
}

template <class CharT>
void StringBase<CharT>::releaseBuffer()
{
	ScopedCriticalSection lock(getStringCriticalSection<CharT>());
	if (m_data)
	{
		if (--m_data->refCount == 0)
			free(m_data);
		m_data = 0;
	}
}

