// The buffer core (target: ensureUniqueBufferOfSize char 0x000364A0, wide 0x00036F00):
// in place when the buffer is unshared and has room (copy, append, terminate);
// otherwise, when appending to a full buffer, grow to half again its capacity;
// allocate the 8-byte header plus the characters rounded to four bytes (more than
// 0x7FFF throws 1), keep the old text when asked, copy, append, terminate and
// release the old buffer.
template <class CharT>
void StringBase<CharT>::ensureUniqueBufferOfSize(int numCharsNeeded, bool preserveData,
	const CharSource<CharT> *strToCopy, const CharSource<CharT> *strToCat)
{
	if (m_data)
	{
		if (m_data->capacity > numCharsNeeded)
		{
			if (m_data->refCount == 1)
			{
				if (strToCopy)
					m_data->length = (unsigned short)strToCopy->getChars(peek());
				if (strToCat)
				{
					CharT *dest = peek() + m_data->length;
					unsigned short n = (unsigned short)strToCat->getChars(dest);
					m_data->length += n;
				}
				peek()[m_data->length] = 0;
				return;
			}
		}
		else if (strToCat)
		{
			unsigned grown = m_data->capacity + m_data->capacity / 2;
			if ((int)grown - 1 > numCharsNeeded)
				numCharsNeeded = (int)grown - 1;
		}
	}

	int minBytes = sizeof(int) + 2 * sizeof(unsigned short) + (numCharsNeeded + 1) * sizeof(CharT);
	if (minBytes > 0x7fff)
		throw 1;
	int actualBytes = (minBytes + 3) / 4 * 4;

	Header *newData = (Header *)_STL::allocator<char>::allocate(actualBytes, (const void *)'str');
	newData->refCount = 1;
	newData->capacity = (unsigned short)((actualBytes - 8) / sizeof(CharT));
	if (m_data && preserveData)
	{
		memcpy((CharT *)(newData + 1), peek(), m_data->length * sizeof(CharT));
		newData->length = m_data->length;
	}
	else
	{
		newData->length = 0;
	}
	if (strToCopy)
		newData->length = (unsigned short)strToCopy->getChars((CharT *)(newData + 1));
	if (strToCat)
	{
		CharT *dest = (CharT *)(newData + 1) + newData->length;
		unsigned short n = (unsigned short)strToCat->getChars(dest);
		newData->length += n;
	}
	((CharT *)(newData + 1))[newData->length] = 0;

	releaseBuffer();
	m_data = newData;
}

template void StringBase<char>::ensureUniqueBufferOfSize(int, bool, const CharSource<char> *, const CharSource<char> *);
