// set(text, length) (char 0x00036780, wide 0x000371E0) and concat(text, length)
// (char 0x000369A0, wide 0x00037410): the text wrapped in a stack source for the
// buffer core; setting a string to its own text does nothing, a zero length
// empties it, concatenating to an empty string is a set.
template <>
void StringBase<char>::set(const char *s, int len)
{
	if (m_data && s == peek())
		return;
	if (len)
	{
		NarrowStrLenSource source(s, len);
		ensureUniqueBufferOfSize(len, false, &source, NULL);
	}
	else
	{
		releaseBuffer();
	}
}

template <>
void StringBase<unsigned short>::set(const unsigned short *s, int len)
{
	if (m_data && s == peek())
		return;
	if (len)
	{
		WideStrLenSource source(s, len);
		ensureUniqueBufferOfSize(len, false, &source, NULL);
	}
	else
	{
		releaseBuffer();
	}
}

template <>
void StringBase<char>::concat(const char *s, int len)
{
	if (len == 0)
		return;
	if (m_data)
	{
		NarrowStrLenSource source(s, len);
		ensureUniqueBufferOfSize(m_data->length + len, true, NULL, &source);
		return;
	}
	set(s, len);
}

template <>
void StringBase<unsigned short>::concat(const unsigned short *s, int len)
{
	if (len == 0)
		return;
	if (m_data)
	{
		WideStrLenSource source(s, len);
		ensureUniqueBufferOfSize(m_data->length + len, true, NULL, &source);
		return;
	}
	set(s, len);
}


