// "StringBase<char>::getBufferForRead"): a unique buffer with room for the count,
// its length set and terminated, for the caller to fill.
template <class CharT>
CharT *StringBase<CharT>::getBufferForRead(int length)
{
	ensureUniqueBufferOfSize(length, false, NULL, NULL);
	if (m_data)
	{
		m_data->length = (unsigned short)length;
		peek()[length] = 0;
	}
	return peek();
}

