// nextToken (char 0x00036D90): destructive tokenizer. The token goes to *token,
// this string keeps the rest after it; with no token both are emptied. The
// separators default to space, LF, CR and TAB. skipSeps/skipNonSeps 0x00035D70 /
// 0x00035DB0 are file statics (retail passes their arguments in registers).
template <>
bool StringBase<char>::nextToken(StringBase<char> *token, const char *delimiters)
{
	Header *data = m_data;
	if (data == 0 || data->length == 0 || token == this)
		return false;
	if (delimiters == 0)
		delimiters = " \n\r\t";
	char *start = skipSeps((char *)(data + 1), delimiters);
	char *end = skipNonSeps(start, delimiters);
	if (end > start)
	{
		int len = (int)(end - start);
		char *dest = token->getBufferForRead(len);
		memcpy(dest, start, len);
		dest[len] = 0;
		int total = m_data ? m_data->length : 0;
		set(end, (int)((char *)m_data - end) + total + (int)sizeof(Header));
		return true;
	}
	releaseBuffer();
	token->releaseBuffer();
	return false;
}

// The wide nextToken (0x00037830): as the char form, with the wide separators
// 0x00035ED0 / 0x00035F20 and the remainder length counted in characters.
template <>
bool StringBase<unsigned short>::nextToken(StringBase<unsigned short> *token, const unsigned short *delimiters)
{
	Header *data = m_data;
	if (data == 0 || data->length == 0 || token == this)
		return false;
	if (delimiters == 0)
		delimiters = L" \n\r\t";
	unsigned short *start = skipSepsW((unsigned short *)(data + 1), delimiters);
	unsigned short *end = skipNonSepsW(start, delimiters);
	if (end > start)
	{
		int len = (int)(end - start);
		unsigned short *dest = token->getBufferForRead(len);
		memcpy(dest, start, len * 2);
		dest[len] = 0;
		int total = m_data ? m_data->length : 0;
		set(end, total - ((int)((char *)end - (char *)m_data - 8) >> 1));
		return true;
	}
	releaseBuffer();
	token->releaseBuffer();
	return false;
}

// The formatters (target: format_va char 0x00036D40, wide 0x000377E0): an
// 8192-character stack buffer filled by the CRT's counted formatter, then the
// length-taking set.
template <>
void StringBase<char>::format_va(const char *fmt, char *args)
{
	char buffer[8192];
	int length = StringCRT::_vsnprintf(buffer, 8192, fmt, args);
	set(buffer, length);
}

template <>
void StringBase<unsigned short>::format_va(const unsigned short *fmt, char *args)
{
	unsigned short buffer[8192];
	int length = StringCRT::_vsnwprintf(buffer, 8192, fmt, args);
	set(buffer, length);
}

