// length of a non-null text (char: the inline strlen scan; wide: msvcr71's
// wcslen through the import, IAT 0x00BBA6AC).
template <>
StringBase<char>::StringBase(const char *s)
{
	m_data = 0;
	set(s, s ? (int)strlen(s) : 0);
}

template <>
StringBase<unsigned short>::StringBase(const unsigned short *s)
{
	m_data = 0;
	set(s, s ? (int)StringCRT::wcslen(s) : 0);
}

